 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The horizontal fragments are rulers: each gets completed through the gaps
    # between its colored cells, while retaining the same row.
    for r, row in enumerate(grid):
        xs = [c for c, v in enumerate(row) if v]
        if xs:
            color = row[xs[0]]
            for c in range(min(xs), max(xs) + 1):
                out[r][c] = color
    # Repeated vertical bars are extended to the top, stopping where their
    # corresponding colored horizontal segment occurs.
    vertical = {}
    for c in range(w):
        for r in range(h):
            color = grid[r][c]
            if color and sum(grid[rr][c] == color for rr in range(h)) > 1:
                vertical[c] = color
                break
    for c, color in vertical.items():
        first = min(r for r in range(h) if grid[r][c] == color)
        # These bars are at the bottom; extend up, but don't overwrite existing lines.
        for r in range(first - 1, -1, -1):
            if out[r][c] != 0:
                break
            out[r][c] = color
    # Singleton marker indicates the other vertical bar's color, aligned to its column;
    # extend it from the bottom edge upward until the horizontal bar boundary.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and sum(v == color for row in grid for v in row) == 1:
                # extend vertical from this bottom marker up to first row containing any horizontal ruler
                for rr in range(r - 1, -1, -1):
                    if any(grid[rr][cc] != 0 for cc in range(w)):
                        break
                    out[rr][c] = color
                return out
    return out
