 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fill the missing cells between occurrences of each horizontal color.
    horizontal_colors = set()
    for r, row in enumerate(grid):
        for color in set(row) - {0}:
            xs = [c for c, v in enumerate(row) if v == color]
            if len(xs) >= 2:
                horizontal_colors.add(color)
                for c in range(min(xs), max(xs) + 1):
                    if out[r][c] == 0:
                        out[r][c] = color
    # If a horizontal color also forms a vertical fragment, continue that
    # vertical line upward from the corresponding horizontal bar.
    for c in range(w):
        for color in horizontal_colors:
            rs = [r for r in range(h) if grid[r][c] == color]
            if len(rs) >= 2:
                above = [r for r in range(h) if color in grid[r] and r < min(rs)]
                if above:
                    bar = max(above)
                    for r in range(bar + 1):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out

if __name__ == '__main__':
