 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fill gaps within each horizontal colored fragment.
    horiz_rows = []
    for r, row in enumerate(grid):
        xs = [c for c, value in enumerate(row) if value]
        if len(xs) >= 2:
            horiz_rows.append(r)
            color = row[xs[0]]
            for c in range(min(xs), max(xs) + 1):
                out[r][c] = color
    # Vertical colored fragments extend upward to the top edge, preserving
    # horizontal lines at crossings. Multi-cell bars are vertically oriented
    # when their color has repeated cells in one column.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                counts[v] = counts.get(v, 0) + 1
    for c in range(w):
        for color, total in counts.items():
            rs = [r for r in range(h) if grid[r][c] == color]
            if len(rs) >= 2 and color not in {grid[r][xs[0]] for r in horiz_rows for xs in [[ [cc for cc,v in enumerate(grid[r]) if v] ][0]]}:
                for r in range(min(rs)):
                    if out[r][c] == 0:
                        out[r][c] = color
    # Isolated marker colors (single cells) are vertical continuation cues.
    for color, total in counts.items():
        if total == 1:
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == color:
                        for rr in range(r):
                            if out[rr][c] == 0:
                                out[rr][c] = color
                        break
    return out

if __name__ == '__main__':
